/* Fotos de retiros — carga lazy */
(function(){
  var photos = {"cr": "data:image/jpeg;base64,", "bog": "data:image/jpeg;base64,"};
  document.addEventListener('DOMContentLoaded', function(){
    var imgs = document.querySelectorAll('[data-photo]');
    imgs.forEach(function(img){
      img.src = photos[img.dataset.photo];
    });
  });
})();
